package br.com.node.mempool;
import br.com.node.transformacao.mempool.*;
import br.com.node.transformacao.nucleo.*;


import static org.junit.jupiter.api.Assertions.assertArrayEquals;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.math.BigInteger;
import java.util.HexFormat;
import java.util.Optional;

import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import br.com.node.vo.SwapPendente;

class RoteadorAgregadorTest {

	
	
	private static final String CALLDATA_3_ROTAS_BNB = "";

	
	
	private static final String CALLDATA_3_ROTAS_ERC20 = "";

	
	
	private static final String CALLDATA_2_ROTAS = "";

	private static final byte[] WBNB = hex("bb4cdb9cbd36b01bd1cbaebf2de08d9173bc095c");
	private static final byte[] USDT = hex("55d398326f99059ff775485246999027b3197955");

	@Test
	@DisplayName("3 rotas com BNB nativo: converte srcToken para WBNB, extrai pools e caminho")
	void tresRotasBnbNativo() {
		Optional<SwapPendente> opt = RoteadorAgregador.decodificar(hex(CALLDATA_3_ROTAS_BNB));
		assertTrue(opt.isPresent(), "não decodificou 3-rotas BNB");

		SwapPendente swap = opt.get();
		assertEquals(new BigInteger("300000000000000000"), swap.entra(), "srcAmount");

		
		assertArrayEquals(WBNB, swap.caminho().get(0), "caminho[0] deve ser WBNB");
		
		assertEquals(4, swap.caminho().size(), "caminho.size");

		
		assertEquals(3, swap.pools().size(), "pools.size");
		assertArrayEquals(hex("306cd1b67f53b3ec51dabe461c1b7c219a951a3c"), swap.pools().get(0), "pool[0]");
		assertArrayEquals(hex("93da00e3ea7b6d18dcb890f03204f060134c2b42"), swap.pools().get(1), "pool[1]");
		assertArrayEquals(hex("b842d65131f21d86141431df2d406ec05dfda97a"), swap.pools().get(2), "pool[2]");

		
		assertArrayEquals(USDT, swap.caminho().get(1), "caminho[1]=USDT");
		assertArrayEquals(hex("5b1910eaad6450e50f816082aa078c41f10c292f"), swap.caminho().get(2), "caminho[2]");
		assertArrayEquals(hex("a17df9706f3be0ae1bd3c90003f279d124577777"), swap.caminho().get(3), "caminho[3]");
	}

	@Test
	@DisplayName("3 rotas com ERC-20 como origem: srcToken preservado, caminho e pools corretos")
	void tresRotasErc20() {
		Optional<SwapPendente> opt = RoteadorAgregador.decodificar(hex(CALLDATA_3_ROTAS_ERC20));
		assertTrue(opt.isPresent(), "não decodificou 3-rotas ERC20");

		SwapPendente swap = opt.get();
		assertEquals(new BigInteger("13107000000000000"), swap.entra(), "srcAmount");

		assertArrayEquals(hex("9b8e987e6fec8cf1380c4dca7071e2c7853aeea1"), swap.caminho().get(0), "srcToken");
		assertEquals(4, swap.caminho().size(), "caminho.size");

		assertEquals(3, swap.pools().size(), "pools.size");
		assertArrayEquals(hex("c07fceeb5e302a2c0bb484d8028c381ec5270b8d"), swap.pools().get(0), "pool[0]");
		assertArrayEquals(hex("306cd1b67f53b3ec51dabe461c1b7c219a951a3c"), swap.pools().get(1), "pool[1]");
		assertArrayEquals(hex("8d8112b0a09c12abe383d249a8f604cfccb40041"), swap.pools().get(2), "pool[2]");
	}

	@Test
	@DisplayName("2 rotas: USDT → intermediário → destino")
	void duasRotas() {
		Optional<SwapPendente> opt = RoteadorAgregador.decodificar(hex(CALLDATA_2_ROTAS));
		assertTrue(opt.isPresent(), "não decodificou 2-rotas");

		SwapPendente swap = opt.get();
		assertEquals(new BigInteger("5000000000000000000"), swap.entra(), "srcAmount");

		assertArrayEquals(USDT, swap.caminho().get(0), "srcToken=USDT");
		assertEquals(3, swap.caminho().size(), "caminho.size");

		assertEquals(2, swap.pools().size(), "pools.size");
		assertArrayEquals(hex("07ab12de339237a5a12f8bf9083d050d27720769"), swap.pools().get(0), "pool[0]");
		assertArrayEquals(hex("43c8e0ca2b81d8ccaa02bb277aed5850dd17ded2"), swap.pools().get(1), "pool[1]");

		assertArrayEquals(hex("205812cdbed920aff76c6580abd681a46d11efc7"), swap.caminho().get(1), "caminho[1]");
		assertArrayEquals(hex("4723a8d92d6e18c3f7c46d8e3743947f3fd67777"), swap.caminho().get(2), "caminho[2]");
	}

	@Test
	@DisplayName("seletor errado retorna vazio")
	void seletorErrado() {
		byte[] errado = hex(CALLDATA_3_ROTAS_BNB);
		errado[0] = (byte) 0xAA;
		assertTrue(RoteadorAgregador.decodificar(errado).isEmpty());
	}

	private static byte[] hex(String s) {
		return HexFormat.of().parseHex(s);
	}
}